import {createStructuredConsumerAdapter} from './adapters/structured-documents.js';
import {createStructuredNoteContentCompatibilityAdapter,NOTE_CONTENT_COMPATIBILITY_CONTRACT} from './adapters/structured-note-content-compatibility.js';
import {FIXTURES,STRUCTURE_TREE,NOTE_FIXTURES} from './adapters/library-fixtures.js';
import {SemanticCommandBus,SEMANTIC_COMMAND_BUS_OWNER} from './foundation/global/commands.js';
import {GlobalInputKeymapOwner,GLOBAL_INPUT_KEYMAP_OWNER} from './foundation/global/input-keymap.js';
import {StructuredSurfaceHost} from './foundation/structured/surface-host.js';
import {StructuredBlockRenderer,structuredBlockRendererPresentationPolicy,setStructuredBlockRendererPresentationPolicy} from './foundation/structured/block-renderer.js';
import {StructuredPresentationBridge} from './foundation/structured/presentation-bridge.js';
import {StructuredNavigationDescriptorOwner,structuredNavigationDescriptorPolicy} from './foundation/structured/outline-descriptor.js';
import {StructuredDocumentDomainAdapter,STRUCTURED_TREE_KERNEL,STRUCTURED_MUTATION_KERNEL} from './foundation/structured.js';

const libraryBundle={initialDocumentId:'KU-D05-0021',FIXTURES,STRUCTURE_TREE,NOTE_FIXTURES};
const assert=(condition,message)=>{if(!condition)throw Error(message);};
const clone=value=>structuredClone(value);
const run=(id,fn)=>{try{return {id,status:'PASS',evidence:fn()}}catch(error){return {id,status:'FAIL',error:String(error?.stack||error)}}};
const eventFor=(key,extra={})=>({key,code:key,defaultPrevented:false,preventDefault(){this.defaultPrevented=true;},stopPropagation(){this.stopped=true;},...extra});
const ids=Object.freeze({library:{paragraph:'blk-d05-p1',toggle:'blk-d05-t1',nested:'blk-d05-li1a'},learn:{paragraph:'learn-p1',toggle:null,nested:null},note:{paragraph:'note-p1',toggle:'note-toggle-1',nested:'note-toggle-p1'}});

function makeConsumer(kind){
  const adapter=kind==='library'?createStructuredConsumerAdapter('library',libraryBundle):kind==='learn'?createStructuredConsumerAdapter('learn'):createStructuredNoteContentCompatibilityAdapter();
  const commands=new SemanticCommandBus();
  const globalInputKeymapOwner=new GlobalInputKeymapOwner({commands});
  const host=new StructuredSurfaceHost({adapter,commands,globalInputKeymapOwner});
  const navigation=new StructuredNavigationDescriptorOwner({adapter});
  return {kind,adapter,commands,globalInputKeymapOwner,host,navigation,ids:ids[kind]};
}
const trio=()=>['library','learn','note'].map(makeConsumer);
const ownerVector=consumer=>{const d=consumer.host.descriptor();return {tree:d.treeOwner,mutation:d.mutationOwner,transaction:d.transactionOwner,selection:d.selectionOwner,clipboard:d.clipboardOwner,input:d.inputKeymapOwner,action:d.actionOwner,direction:d.directionOwner,rich:d.richContentOwner,drag:d.dragDropOwner,renderer:d.rendererOwner,presentation:d.presentationBridgeOwner,commands:d.commands,globalInput:d.globalInputOwner,navigation:consumer.navigation.owner};};
const snapshotTruth=consumer=>({document:JSON.stringify(consumer.adapter.snapshot()),transaction:JSON.stringify(consumer.adapter.transactionDescriptor()),selection:JSON.stringify(consumer.adapter.selection.descriptor()),selectionReceipts:consumer.adapter.selection.receipts().length});
const truthUnchanged=(before,consumer)=>before.document===JSON.stringify(consumer.adapter.snapshot())&&before.transaction===JSON.stringify(consumer.adapter.transactionDescriptor())&&before.selection===JSON.stringify(consumer.adapter.selection.descriptor())&&before.selectionReceipts===consumer.adapter.selection.receipts().length;

export function runW5CStructuredConsumerParityProof(){
  const cases=[];
  cases.push(run('w5c.same-host-class-all-three-consumers',()=>{const consumers=trio();assert(consumers.every(c=>c.host.constructor===StructuredSurfaceHost&&Object.getPrototypeOf(c.host)===StructuredSurfaceHost.prototype),'consumer-specific StructuredSurfaceHost implementation detected');return Object.fromEntries(consumers.map(c=>[c.kind,{hostClass:c.host.constructor.name,hostOwner:c.host.owner,domainOwner:c.adapter.owner,domainKind:c.adapter.domainKind}]))}));
  cases.push(run('w5c.same-canonical-adapter-model-all-three',()=>{const consumers=trio();assert(consumers.every(c=>c.adapter.constructor===StructuredDocumentDomainAdapter&&Object.getPrototypeOf(c.adapter)===StructuredDocumentDomainAdapter.prototype),'consumer-specific document adapter implementation detected');assert(consumers.every(c=>c.adapter.treeKernel===STRUCTURED_TREE_KERNEL&&c.adapter.mutationKernel===STRUCTURED_MUTATION_KERNEL),'canonical tree/mutation kernel identity diverged');return {adapterClass:'StructuredDocumentDomainAdapter',sharedTreeObject:consumers.every(c=>c.adapter.treeKernel===consumers[0].adapter.treeKernel),sharedMutationObject:consumers.every(c=>c.adapter.mutationKernel===consumers[0].adapter.mutationKernel),documents:consumers.map(c=>({consumer:c.kind,id:c.adapter.snapshot().id,owner:c.adapter.owner}))};}));
  cases.push(run('w5c.exact-owner-coherence-vector',()=>{const consumers=trio(),vectors=consumers.map(ownerVector),expected={tree:'StructuredTreeKernel',mutation:'StructuredMutationKernel',transaction:'StructuredTransactionHistoryRecoveryOwner',selection:'StructuredSelectionKernel',clipboard:'StructuredClipboardTrustOwner',input:'StructuredInputKeymapOwner',action:'StructuredActionDescriptorOwner',direction:'InputDirectionResolver',rich:'StructuredRichContentOwner',drag:'StructuredDragDropOwner',renderer:'StructuredBlockRenderer',presentation:'StructuredPresentationBridge',commands:SEMANTIC_COMMAND_BUS_OWNER,globalInput:GLOBAL_INPUT_KEYMAP_OWNER,navigation:'StructuredNavigationDescriptorOwner'};assert(vectors.every(v=>JSON.stringify(v)===JSON.stringify(expected)),'accepted owner vector diverged across consumers');return {expected,consumers:Object.fromEntries(consumers.map((c,i)=>[c.kind,vectors[i]]))};}));
  cases.push(run('w5c.note-content-boundary-content-only',()=>{const note=makeConsumer('note'),contract=note.adapter.noteContentCompatibilityContract;assert(contract===NOTE_CONTENT_COMPATIBILITY_CONTRACT&&contract.purpose==='CONTENT_COMPATIBILITY_ONLY'&&!contract.semanticOwner&&!contract.stickyNoteWindowOwnerImplemented&&!contract.finalNoteBindingAdapterImplemented&&!contract.popoutLifecycleImplemented&&!contract.pinAlwaysOnTopImplemented&&!contract.secondEditorEngineImplemented,'Note content fixture exceeded Lane C boundary');assert(note.adapter.domainKind==='note-content'&&note.host.constructor===StructuredSurfaceHost,'Note content fixture created a second editor engine');return {contract,adapterOwner:note.adapter.owner,hostOwner:note.host.owner};}));
  cases.push(run('w5c.canonical-block-identity-path-projection-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){const target=c.ids.nested||c.ids.paragraph,projection=c.host.project(),node=c.host.renderer.find(projection.render,target),canonical=c.adapter.treeKernel.pathFor(c.adapter.snapshot().blocks,target).map(x=>x.id);assert(node&&node.canonicalBlockId===target&&JSON.stringify(node.canonicalPath)===JSON.stringify(canonical),'canonical identity/path projection diverged:'+c.kind);evidence[c.kind]={documentId:projection.documentId,blockId:target,path:node.canonicalPath,depth:node.depth,rendererOwner:node.owner};}return evidence;}));
  cases.push(run('w5c.read-mode-denies-canonical-mutation-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){const before=snapshotTruth(c);c.host.setMode('read');const content=c.host.updateContent(c.ids.paragraph,{html:'forbidden'}),action=c.host.routeAction('block.duplicate',{blockId:c.ids.paragraph}),command=c.host.routeCommand('block.background',{blockId:c.ids.paragraph,value:'soft'}),keyboard=c.host.reorderKeyboard(c.ids.paragraph,'down'),begin=c.host.beginPointerDrag({sourceBlockId:c.ids.paragraph,pointerId:77,startX:0,startY:0});assert([content,action,command,keyboard,begin].every(x=>x?.ok===false),'read mode mutation route unexpectedly enabled:'+c.kind);assert(truthUnchanged(before,c),'read mode changed canonical truth:'+c.kind);evidence[c.kind]={content:content.code,action:action.code,command:command.code,keyboard:keyboard.code,pointer:begin.code,canonicalUnchanged:true};}return evidence;}));
  cases.push(run('w5c.edit-content-mutation-transaction-owner-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){const beforeDoc=c.adapter.snapshot(),beforeTx=c.adapter.transactionDescriptor(),result=c.host.updateContent(c.ids.paragraph,{html:`تحديث Lane C عبر ${c.kind} · <bdi dir="ltr">accepted transaction</bdi>`}),afterTx=c.adapter.transactionDescriptor();assert(result.ok&&result.changed&&result.delegatedOwner==='StructuredTransactionHistoryRecoveryOwner'&&result.historyFrameDelta===1&&afterTx.historyLength===beforeTx.historyLength+1&&afterTx.workingRevision===beforeTx.workingRevision+1,'edit content bypassed transaction owner:'+c.kind);c.adapter.undo();assert(JSON.stringify(c.adapter.snapshot())===JSON.stringify(beforeDoc),'edit content exact undo failed:'+c.kind);evidence[c.kind]={code:result.code,transactionOwner:result.delegatedOwner,historyFrameDelta:result.historyFrameDelta,undoExact:true};}return evidence;}));
  cases.push(run('w5c.selection-owner-pointer-route-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){const result=c.host.routePointerSelection(c.ids.paragraph);assert(result.owner==='StructuredSelectionKernel'&&result.delegatedOwner==='StructuredSelectionKernel'&&result.blockIds.includes(c.ids.paragraph),'selection owner bypass:'+c.kind);evidence[c.kind]={owner:result.owner,selected:result.blockIds};}return evidence;}));
  cases.push(run('w5c.keyboard-command-route-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){const before=c.adapter.snapshot(),beforeTx=c.adapter.transactionDescriptor(),newId=`${c.kind}-w5c-enter`,event=eventFor('Enter'),route=c.host.routeKeydown(event,{caret:{blockId:c.ids.paragraph,beforeText:'Lane C keyboard',afterText:'',beforeHtml:'Lane C keyboard',afterHtml:'',atStart:false,atEnd:true},allocateBlockId:()=>newId}),afterTx=c.adapter.transactionDescriptor();assert(route.globalResult.owner==='GlobalInputKeymapOwner'&&route.result.owner==='StructuredInputKeymapOwner'&&route.result.handled&&route.result.command==='block.split'&&route.result.availability.availabilityOwner==='StructuredCommandAvailabilityOwner'&&route.result.result.semanticOwner==='StructuredMutationKernel'&&afterTx.historyLength===beforeTx.historyLength+1,'keyboard route owner graph diverged:'+c.kind);c.adapter.undo();assert(JSON.stringify(c.adapter.snapshot())===JSON.stringify(before),'keyboard exact undo failed:'+c.kind);evidence[c.kind]={globalOwner:route.globalResult.owner,inputOwner:route.result.owner,command:route.result.command,availabilityOwner:route.result.availability.availabilityOwner,mutationOwner:route.result.result.semanticOwner,transactionOwner:c.adapter.transactionOwner.owner,undoExact:true};}return evidence;}));
  cases.push(run('w5c.clipboard-owner-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){c.host.routePointerSelection(c.ids.paragraph);const before=JSON.stringify(c.adapter.snapshot()),result=c.host.routeClipboard('document.copy'),after=JSON.stringify(c.adapter.snapshot()),receipt=c.commands.lastReceipt();assert(result.ok&&result.owner==='StructuredClipboardTrustOwner'&&result.delegatedOwner==='StructuredClipboardTrustOwner'&&receipt?.owner==='StructuredClipboardTrustOwner'&&before===after,'clipboard ownership or no-mutation law failed:'+c.kind);evidence[c.kind]={owner:result.owner,busOwner:receipt.owner,documentUnchanged:true,payloadBlocks:result.payload.blocks.map(x=>x.id)};}return evidence;}));
  cases.push(run('w5c.action-descriptor-owner-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){const before=c.adapter.snapshot(),beforeTx=c.adapter.transactionDescriptor(),result=c.host.routeAction('block.duplicate',{blockId:c.ids.paragraph,surface:'block-menu'}),afterTx=c.adapter.transactionDescriptor();assert(result.ok&&result.descriptorOwner==='StructuredActionDescriptorOwner'&&result.delegatedOwner==='StructuredActionDescriptorOwner'&&result.delegation.availabilityOwner==='StructuredCommandAvailabilityOwner'&&result.delegation.mutationOwner==='StructuredMutationKernel'&&result.delegation.transactionOwner==='StructuredTransactionHistoryRecoveryOwner'&&afterTx.historyLength===beforeTx.historyLength+1,'action descriptor route failed:'+c.kind);c.adapter.undo();assert(JSON.stringify(c.adapter.snapshot())===JSON.stringify(before),'action duplicate exact undo failed:'+c.kind);evidence[c.kind]={descriptorOwner:result.descriptorOwner,delegation:result.delegation,historyDelta:1,undoExact:true};}return evidence;}));
  cases.push(run('w5c.direction-rich-content-projection-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){const projection=c.host.project(),node=c.host.renderer.find(projection.render,c.ids.paragraph);assert(node?.richContentOwner==='StructuredRichContentOwner'&&node?.directionOwner==='InputDirectionResolver'&&['rtl','ltr'].includes(node.direction),'rich/direction owner projection failed:'+c.kind);evidence[c.kind]={richContentOwner:node.richContentOwner,directionOwner:node.directionOwner,direction:node.direction,contentSource:node.contentSource};}return evidence;}));
  cases.push(run('w5c.toggle-rich-title-sanitization-real-compatible-consumers',()=>{const evidence={};for(const kind of ['library','note']){const c=makeConsumer(kind),toggle=c.ids.toggle,raw='<strong>SAFE</strong><img src=x onerror=alert(1)>مرحبا <bdi dir="ltr">TCP/IP</bdi>',result=c.host.updateContent(toggle,{title:'PLAIN',titleHtml:raw}),node=c.host.renderer.find(c.host.project().render,toggle);assert(result.ok&&node.contentSource==='titleHtml'&&node.html.includes('<strong>SAFE</strong>')&&!/<img|onerror\s*=/i.test(node.html)&&node.richContentOwner==='StructuredRichContentOwner'&&node.directionOwner==='InputDirectionResolver','toggle rich title did not use accepted sanitization/direction path:'+kind);evidence[kind]={source:node.contentSource,sanitized:true,richContentOwner:node.richContentOwner,directionOwner:node.directionOwner};}return evidence;}));
  cases.push(run('w5c.content-field-applicability-type-truth-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){const before=snapshotTruth(c);let error='';try{c.host.updateContent(c.ids.paragraph,{title:'illegal-on-paragraph'})}catch(value){error=String(value?.message||value)}assert(error==='STRUCTURED_CONTENT_FIELD_NOT_APPLICABLE:paragraph:title'&&truthUnchanged(before,c),'content applicability/type preflight failed:'+c.kind);evidence[c.kind]={error,zeroTransactionSideEffects:true};}return evidence;}));
  cases.push(run('w5c.drag-keyboard-shared-target-policy-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){const before=c.adapter.snapshot(),result=c.host.reorderKeyboard(c.ids.paragraph,'down');assert(result.ok&&result.changed&&result.delegatedOwner==='StructuredDragDropOwner'&&result.validation?.owner==='StructuredDropTargetPolicyOwner','keyboard drag target policy bypass:'+c.kind);c.adapter.undo();assert(JSON.stringify(c.adapter.snapshot())===JSON.stringify(before),'keyboard drag exact undo failed:'+c.kind);evidence[c.kind]={dragOwner:result.delegatedOwner,targetPolicyOwner:result.validation.owner,targetIdentity:result.validation.targetIdentity,undoExact:true};}return evidence;}));
  cases.push(run('w5c.drag-pointer-shared-target-policy-all-three',()=>{const consumers=trio(),evidence={};let pointerId=100;for(const c of consumers){const before=c.adapter.snapshot(),beforeTx=c.adapter.transactionDescriptor(),index=c.adapter.snapshot().blocks.length,begin=c.host.beginPointerDrag({sourceBlockId:c.ids.paragraph,pointerId:++pointerId,startX:0,startY:0}),update=c.host.updatePointerDrag({clientX:20,clientY:20,target:{kind:'gap',parentId:null,index,depth:0},viewportTop:0,viewportBottom:700}),commit=c.host.commitPointerDrag(),afterTx=c.adapter.transactionDescriptor();assert(begin.ok&&update.active&&update.validation?.owner==='StructuredDropTargetPolicyOwner'&&commit.ok&&commit.changed&&commit.delegatedOwner==='StructuredDragDropOwner'&&commit.receipt?.mutationOwner==='StructuredMutationKernel'&&commit.receipt?.transactionOwner==='StructuredTransactionHistoryRecoveryOwner'&&afterTx.historyLength===beforeTx.historyLength+1,'pointer drag owner graph failed:'+c.kind);c.adapter.undo();assert(JSON.stringify(c.adapter.snapshot())===JSON.stringify(before),'pointer drag exact undo failed:'+c.kind);evidence[c.kind]={dragOwner:commit.delegatedOwner,targetPolicyOwner:commit.targetPolicyOwner,mutationOwner:commit.receipt.mutationOwner,transactionOwner:commit.receipt.transactionOwner,historyFrameDelta:commit.historyFrameDelta,undoExact:true};}return evidence;}));
  cases.push(run('w5c.navigation-descriptor-presentation-only-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){const before=snapshotTruth(c),descriptor=c.navigation.descriptor(),inspection=c.navigation.readInspection(c.ids.paragraph,{mode:'read'});assert(descriptor.owner==='StructuredNavigationDescriptorOwner'&&descriptor.outline.canonicalTreeOwner==='StructuredTreeKernel'&&descriptor.quickJump.domIdentityCanonical===false&&descriptor.quickJump.performsDomScroll===false&&inspection.eligible&&inspection.behavior.mutatesDocument===false&&inspection.behavior.activatesEditSelection===false&&inspection.behavior.capturesWriterFocus===false&&inspection.behavior.performsDomScroll===false&&truthUnchanged(before,c),'navigation descriptor mutated/claimed forbidden truth:'+c.kind);evidence[c.kind]={outlineCount:descriptor.outline.count,quickJumpCount:descriptor.quickJump.count,inspectionCode:inspection.code,presentationDelegation:descriptor.presentationDelegation,canonicalTruthUnchanged:true};}return evidence;}));
  cases.push(run('w5c.navigation-fake-tree-authority-rejected',()=>{const c=makeConsumer('note'),fake={...c.adapter.treeKernel,owner:'StructuredTreeKernel'};let constructorError='',driftError='';try{new StructuredNavigationDescriptorOwner({adapter:c.adapter,treeKernel:fake})}catch(value){constructorError=String(value?.message||value)}const nav=new StructuredNavigationDescriptorOwner({adapter:c.adapter});nav.treeKernel=fake;try{nav.descriptor()}catch(value){driftError=String(value?.message||value)}assert(constructorError==='STRUCTURED_NAVIGATION_ADAPTER_TREE_KERNEL_MISMATCH'&&driftError==='CANONICAL_STRUCTURED_TREE_KERNEL_REQUIRED','navigation helper accepted fake tree authority');return {constructorError,postConstructionDriftError:driftError,fakeOwnerNameNotSufficient:true};}));
  cases.push(run('w5c.global-input-command-bus-coherence-all-three',()=>{const consumers=trio(),evidence={};for(const c of consumers){assert(c.commands.constructor===SemanticCommandBus&&c.globalInputKeymapOwner.constructor===GlobalInputKeymapOwner&&c.globalInputKeymapOwner.commands===c.commands&&c.host.commands===c.commands&&c.host.globalInputKeymapOwner===c.globalInputKeymapOwner&&c.adapter.inputKeymapOwner.commands===c.commands&&c.adapter.inputKeymapOwner.globalInputKeymapOwner===c.globalInputKeymapOwner,'global input / command bus coherence failed:'+c.kind);evidence[c.kind]={commandAuthority:SEMANTIC_COMMAND_BUS_OWNER,globalInputOwner:c.globalInputKeymapOwner.owner,sameBusInstanceWithinConsumer:true};}return evidence;}));
  cases.push(run('w5c.post-construction-command-drift-refused-before-effect',()=>{const c=makeConsumer('note'),before=snapshotTruth(c),original=c.commands.commands.get('block.align'),replacement={...original,run(){throw Error('FAKE_COMMAND_EXECUTED')}};c.commands.commands.set('block.align',replacement);let error='';try{c.host.routeCommand('block.align',{blockId:c.ids.paragraph,value:'center'})}catch(value){error=String(value?.message||value)}c.commands.commands.set('block.align',original);assert(error==='STRUCTURED_CANONICAL_COMMAND_BINDING_DRIFT:block.align'&&truthUnchanged(before,c),'post-construction command drift executed or changed truth');return {error,canonicalUnchanged:true,fakeCommandExecuted:false};}));
  cases.push(run('w5c.post-construction-owner-drift-refused-before-effect',()=>{const c=makeConsumer('note'),before=snapshotTruth(c),real=c.adapter.selection;c.adapter.selection={...real,owner:'StructuredSelectionKernel'};let error='';try{c.host.routePointerSelection(c.ids.paragraph)}catch(value){error=String(value?.message||value)}c.adapter.selection=real;assert(['SECOND_STRUCTURED_SELECTION_OWNER_DETECTED','SECOND_STRUCTURED_CLIPBOARD_OWNER_DETECTED'].includes(error)&&truthUnchanged(before,c),'post-construction selection drift executed or changed truth');return {error,canonicalUnchanged:true,driftRejectedBeforeEffect:true};}));
  cases.push(run('w5c.central-renderer-change-reaches-three-and-exact-revert',()=>{const consumers=trio(),beforePolicy=structuredBlockRendererPresentationPolicy(),before=Object.fromEntries(consumers.map(c=>[c.kind,c.host.project().html])),change=setStructuredBlockRendererPresentationPolicy({blockGapPx:beforePolicy.blockGapPx+5,indentUnitPx:beforePolicy.indentUnitPx+3});try{const during=Object.fromEntries(consumers.map(c=>[c.kind,c.host.project().html]));assert(consumers.every(c=>before[c.kind]!==during[c.kind]),'central renderer policy did not reach all consumers');const reverted=change.revert(),after=Object.fromEntries(consumers.map(c=>[c.kind,c.host.project().html]));assert(JSON.stringify(reverted)===JSON.stringify(beforePolicy)&&consumers.every(c=>before[c.kind]===after[c.kind]),'central renderer exact revert failed across consumers');return {beforePolicy,duringPolicy:change.current,reverted,consumers:Object.fromEntries(consumers.map(c=>[c.kind,{changed:before[c.kind]!==during[c.kind],exactRevert:before[c.kind]===after[c.kind]}]))};}finally{if(JSON.stringify(structuredBlockRendererPresentationPolicy())!==JSON.stringify(beforePolicy))setStructuredBlockRendererPresentationPolicy(beforePolicy);}}));
  cases.push(run('w5c.navigation-policy-shared-authority-three-consumers',()=>{const consumers=trio(),policy=structuredNavigationDescriptorPolicy(),descriptors=consumers.map(c=>c.navigation.descriptor());assert(descriptors.every(d=>JSON.stringify(d.policy)===JSON.stringify(policy)&&d.owner==='StructuredNavigationDescriptorOwner'),'navigation policy authority diverged by consumer');return {policy,consumers:Object.fromEntries(consumers.map((c,i)=>[c.kind,{owner:descriptors[i].owner,policy:descriptors[i].policy}]))};}));
  cases.push(run('w5c.renderer-presentation-bridge-exact-class-all-three',()=>{const consumers=trio();assert(consumers.every(c=>c.host.renderer.constructor===StructuredBlockRenderer&&c.host.presentationBridge.constructor===StructuredPresentationBridge&&c.host.presentationBridge.renderer===c.host.renderer&&c.host.renderer.treeKernel===c.adapter.treeKernel&&c.host.renderer.richContentOwner===c.adapter.richContentOwner),'renderer/presentation bridge graph diverged');return Object.fromEntries(consumers.map(c=>[c.kind,{renderer:c.host.renderer.owner,presentation:c.host.presentationBridge.owner,sameRendererBridgeGraph:true}]))}));
  cases.push(run('w5c.no-copied-canonical-document-state-in-host-navigation',()=>{const consumers=trio(),evidence={};for(const c of consumers){const before=JSON.stringify(c.adapter.snapshot()),projection=c.host.project(),outline=c.navigation.outline(),quick=c.navigation.quickJump(),after=JSON.stringify(c.adapter.snapshot());assert(before===after&&c.host.adapter===c.adapter&&c.navigation.adapter===c.adapter&&projection.documentId===c.adapter.identity().id&&outline.documentIdentity.documentId===c.adapter.identity().id&&quick.documentIdentity.documentId===c.adapter.identity().id,'host/navigation created or switched canonical state:'+c.kind);evidence[c.kind]={documentId:projection.documentId,hostUsesAdapter:c.host.adapter===c.adapter,navigationUsesAdapter:c.navigation.adapter===c.adapter,canonicalUnchanged:true};}return evidence;}));
  cases.push(run('w5c.central-owner-change-revert-reaches-replacement-path',()=>{const consumers=trio(),before=Object.fromEntries(consumers.map(c=>[c.kind,{html:c.host.project().html,ownerVector:ownerVector(c)}])),policy=structuredBlockRendererPresentationPolicy(),change=setStructuredBlockRendererPresentationPolicy({blockGapPx:policy.blockGapPx+1});const during=Object.fromEntries(consumers.map(c=>[c.kind,c.host.project().html]));change.revert();const after=Object.fromEntries(consumers.map(c=>[c.kind,{html:c.host.project().html,ownerVector:ownerVector(c)}]));assert(consumers.every(c=>before[c.kind].html!==during[c.kind]&&before[c.kind].html===after[c.kind].html&&JSON.stringify(before[c.kind].ownerVector)===JSON.stringify(after[c.kind].ownerVector)),'central change/revert did not stay on same owner graph');return {consumers:Object.fromEntries(consumers.map(c=>[c.kind,{changed:true,exactRevert:true,ownerGraphStable:true}]))};}));
  const failed=cases.filter(item=>item.status!=='PASS');
  return {schemaVersion:1,kind:'W5_C_STRUCTURED_CONSUMER_PARITY_EXECUTABLE_PROOF',status:failed.length?'FAIL':'PASS',caseCount:cases.length,passCount:cases.length-failed.length,failCount:failed.length,cases};
}
